import { StrictMode } from 'react';
import { act, cleanup, fireEvent, render, screen, within } from '@testing-library/react';
import { afterEach, beforeEach, expect, it, vi } from 'vitest';
import { AgentChatWithHistory } from './AgentChatWithHistory';
const { transport } = vi.hoisted(() => ({ transport: vi.fn() }));
vi.mock('./Settings', () => ({ useSettings: () => ({ settings: { preferences: { defaultProvider: 'alibaba' }, providers: { alibaba: { apiKey: 'local-fixture-key', selectedModel: 'qwen-plus' } } }, updateProvider: vi.fn(), updatePreferences: vi.fn() }) }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (k: string) => k }) }));
vi.mock('@/lib/ai-providers', () => ({ createAIProvider: () => ({ chat: transport }) }));
vi.mock('@/lib/hooks/useModelPricing', () => ({ useModelPricing: () => ({ pricing: {}, status: 'ready', updatedAt: null }) }));
vi.mock('@/lib/quota-manager', async original => ({ ...await original<typeof import('@/lib/quota-manager')>(), useQuotaManager: () => ({ trackUsage: vi.fn(), checkBudget: () => ({ ok: true, remaining: { daily: Infinity, monthly: Infinity } }) }) }));
const KEY='cvf_chat_history'; const WHEN='2026-02-02T00:00:00.000Z';
const saved=(id:string)=>({id,title:'Local '+id,provider:'alibaba',createdAt:WHEN,updatedAt:WHEN,metadata:{messageCount:2,totalTokens:13},messages:[{id:id+'-u',role:'user',content:'question-'+id,timestamp:WHEN},{id:id+'-a',role:'assistant',content:'answer-'+id,timestamp:WHEN}]});
const state=()=>JSON.parse(localStorage.getItem(KEY)!);
const ids=()=>state().sessions.map((s:{id:string})=>s.id);
const rows=()=>screen.queryAllByTitle('Delete').map(b=>b.closest('.group') as HTMLElement);
const row=(title:string)=>rows().find(r=>r.querySelector('span.font-medium')?.textContent===title)!;
const remove=(title:string)=>fireEvent.click(within(row(title)).getByTitle('Delete'));
const tick=(ms=25)=>act(async()=>{await vi.advanceTimersByTimeAsync(ms);});
const send=(text:string)=>{fireEvent.change(screen.getByLabelText('Message input'),{target:{value:text}});fireEvent.click(screen.getByLabelText('Send message'));};
const clear=(choice:string)=>{fireEvent.click(screen.getByText(/Clear All History/));fireEvent.click(screen.getByText(choice));};
const snap=(label:string)=>console.log('LOCAL_SNAPSHOT '+JSON.stringify({label,state:state(),sidebar:rows().map(r=>r.textContent)}));
beforeEach(()=>{vi.useFakeTimers();localStorage.clear();transport.mockReset();transport.mockImplementation(async (m:Array<{content:string}>)=>({text:'LOCAL_REPLY:'+m[m.length-1].content,usage:{totalTokens:2}}));localStorage.setItem(KEY,JSON.stringify({sessions:[saved('one'),saved('two')],activeSessionId:'one'}));});
afterEach(()=>{cleanup();vi.useRealTimers();localStorage.clear();});
it('real send/select/inactive delete survives close/reopen, then clear leaves one empty persisted session',async()=>{
 const fetchSpy=vi.spyOn(globalThis,'fetch');
 const untouched=state().sessions[1];
 const view=render(<StrictMode><AgentChatWithHistory /></StrictMode>);
 expect(screen.getByText('answer-one')).toBeDefined();
 fireEvent.click(screen.getByRole('button',{name:/New Chat/}));await tick(25);
 send('LOCAL_NEW_WORK');await tick(25);const newId=state().activeSessionId;
 expect(rows()).toHaveLength(3);expect(row('LOCAL_NEW_WORK').textContent).toContain('2 msgs');
 expect(state().sessions[0].messages.map((m:{content:string})=>m.content)).toEqual(['LOCAL_NEW_WORK','LOCAL_REPLY:LOCAL_NEW_WORK']);
 expect(screen.getByText('LOCAL_REPLY:LOCAL_NEW_WORK')).toBeDefined();
 fireEvent.click(row('Local two'));await tick();expect(state().activeSessionId).toBe('two');
 expect(screen.queryByText('LOCAL_REPLY:LOCAL_NEW_WORK')).toBeNull();expect(screen.getByText('answer-two')).toBeDefined();
 expect(state().sessions.find((s:{id:string})=>s.id==='two')).toEqual(untouched);
 remove('LOCAL_NEW_WORK');await tick();expect(ids()).not.toContain(newId);expect(state().activeSessionId).toBe('two');
 snap('inactive-delete');view.unmount();
 const reopened=render(<StrictMode><AgentChatWithHistory /></StrictMode>);await tick();
 expect(screen.getByText('answer-two')).toBeDefined();expect(ids()).toEqual(['one','two']);
 const beforeCancel=localStorage.getItem(KEY);clear('Cancel');expect(localStorage.getItem(KEY)).toBe(beforeCancel);
 clear('Confirm');await tick();expect(state().sessions).toHaveLength(1);expect(state().sessions[0].messages).toEqual([]);
 const emptyId=state().activeSessionId;expect(rows()).toHaveLength(1);snap('cleared');reopened.unmount();
 render(<StrictMode><AgentChatWithHistory /></StrictMode>);await tick();
 expect(state().activeSessionId).toBe(emptyId);expect(state().sessions).toHaveLength(1);expect(state().sessions[0].messages).toEqual([]);
 expect(transport).toHaveBeenCalledTimes(1);expect(fetchSpy).not.toHaveBeenCalled();fetchSpy.mockRestore();
});
it('clear cancels queued intake, then deletes an in-flight final session without resurrecting its late result',async()=>{
 const view=render(<StrictMode><AgentChatWithHistory initialPrompt="LOCAL_QUEUED_INTAKE" /></StrictMode>);
 clear('Confirm');await tick(900);expect(transport).not.toHaveBeenCalled();
 expect(state().sessions).toHaveLength(1);expect(state().sessions[0].messages).toEqual([]);
 let resolve!: (v:{text:string;usage:{totalTokens:number}})=>void;
 transport.mockImplementation(()=>new Promise(r=>{resolve=r;}));
 await tick(25);send('LOCAL_INFLIGHT');await tick(25);const removedId=state().activeSessionId;
 expect(transport).toHaveBeenCalledTimes(1);remove('LOCAL_INFLIGHT');await tick();
 const replacementId=state().activeSessionId;expect(replacementId).not.toBe(removedId);expect(state().sessions).toHaveLength(1);
 await act(async()=>{resolve({text:'LOCAL_LATE_RESULT',usage:{totalTokens:1}});});await tick(900);
 expect(ids()).toEqual([replacementId]);expect(JSON.stringify(state())).not.toMatch(/LOCAL_INFLIGHT|LOCAL_LATE_RESULT|LOCAL_QUEUED_INTAKE/);
 expect(state().sessions[0].messages).toEqual([]);expect(rows()).toHaveLength(1);snap('late-final-delete');
 view.unmount();render(<AgentChatWithHistory />);await tick();
 expect(ids()).toEqual([replacementId]);expect(state().sessions[0].messages).toEqual([]);expect(transport).toHaveBeenCalledTimes(1);
});
